<?php
require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security;
Security::startSession();
if(Security::user()){header('Location: dashboard.php');exit;}
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ Security::checkCsrf($_POST['csrf']??null); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $senha=$_POST['senha']??''; $ip=$_SERVER['REMOTE_ADDR']??''; $st=db()->prepare("SELECT COUNT(*) FROM login_attempts WHERE (email=? OR ip=?) AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE) AND success=0"); $st->execute([$email?:'', $ip]); if((int)$st->fetchColumn()>=5){$error='Muitas tentativas. Aguarde 15 minutos.';} else { $st=db()->prepare('SELECT id,nome,email,senha,nivel,status FROM usuarios WHERE email=? LIMIT 1');$st->execute([$email?:'']);$u=$st->fetch();$ok=$u && $u['status'] && password_verify($senha,$u['senha']);$lg=db()->prepare('INSERT INTO login_attempts(email,ip,success) VALUES(?,?,?)');$lg->execute([$email?:'', $ip,$ok?1:0]);if($ok){Security::login($u);header('Location: dashboard.php');exit;}$error='E-mail ou senha inválidos.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login - <?=Security::e(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/app.css"></head><body class="login-page"><main class="login-card"><h1>Controle de Locação</h1><p class="text-secondary">Acesse o painel administrativo</p><?php if($error):?><div class="alert alert-danger"><?=Security::e($error)?></div><?php endif;?><form method="post" novalidate><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="mb-3"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" required autocomplete="username"></div><div class="mb-3"><label class="form-label">Senha</label><input class="form-control" type="password" name="senha" required autocomplete="current-password"></div><button class="btn btn-primary w-100">Entrar</button></form></main></body></html>
